import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  collapsibleContentClassName,
  collapsibleIconClassName,
  collapsiblePanelClassName,
  collapsibleRootClassName,
  collapsibleTriggerClassName,
} from "./view";

export {
  collapsibleContentClassName,
  collapsibleIconClassName,
  collapsiblePanelClassName,
  collapsibleRootClassName,
  collapsibleTriggerClassName,
} from "./view";

export type CollapsibleStyle = Readonly<Record<string, string>>;

export type RootViewConfig = Readonly<{
  /** Whether the panel is currently open. */
  open: boolean;
  /** Trigger and panel children. */
  children: readonly Html[];
  /** Whether the component should ignore trigger interaction. */
  disabled?: boolean | undefined;
  /** Additional class names appended to the default root classes. */
  className?: string | undefined;
  /** Inline styles applied to the root element. */
  style?: CollapsibleStyle | undefined;
}>;

export type TriggerViewConfig<ParentMessage> = Readonly<{
  /** Whether the panel is currently open. */
  open: boolean;
  /** Message sent when the trigger is clicked. */
  onOpenChange: ParentMessage;
  /** Visible trigger content. */
  children: readonly Html[];
  /** Accessible trigger label. Defaults to visible text when omitted. */
  ariaLabel?: string | undefined;
  /** Panel id referenced by aria-controls. */
  panelId?: string | undefined;
  /** Whether the component should ignore trigger interaction. */
  disabled?: boolean | undefined;
  /** Additional class names appended to the default trigger classes. */
  className?: string | undefined;
  /** Inline styles applied to the trigger element. */
  style?: CollapsibleStyle | undefined;
}>;

export type PanelViewConfig = Readonly<{
  /** Whether the panel is currently open. */
  open: boolean;
  /** Panel content. */
  children: readonly Html[];
  /** Panel id referenced by the trigger. */
  id?: string | undefined;
  /** Keep the panel in the DOM while closed using hidden state. */
  keepMounted?: boolean | undefined;
  /** Preserve find-in-page behavior with hidden=until-found while closed. */
  hiddenUntilFound?: boolean | undefined;
  /** Additional class names appended to the default panel classes. */
  className?: string | undefined;
  /** Inline styles applied to the panel element. */
  style?: CollapsibleStyle | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const openAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  open: boolean
) => (open ? [h.DataAttribute("open", "")] : [h.DataAttribute("closed", "")]);

const disabledAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  disabled: boolean
) => (disabled ? [h.DataAttribute("disabled", "")] : []);

export const rootView = <ParentMessage>({
  open,
  children,
  disabled = false,
  className,
  style,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...openAttributes(h, open),
      ...disabledAttributes(h, disabled),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(collapsibleRootClassName, className)),
    ],
    children
  );
};

export const triggerView = <ParentMessage>({
  open,
  onOpenChange,
  children,
  ariaLabel,
  panelId,
  disabled = false,
  className,
  style,
}: TriggerViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.button(
    [
      h.Type("button"),
      ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
      ...(panelId === undefined ? [] : [h.AriaControls(panelId)]),
      h.AriaExpanded(open),
      ...(open ? [h.DataAttribute("panel-open", "")] : []),
      ...disabledAttributes(h, disabled),
      ...(disabled ? [h.Disabled(true)] : [h.OnClick(onOpenChange)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(classNames(collapsibleTriggerClassName, className)),
    ],
    [
      ...children,
      h.span([h.AriaHidden(true), h.Class(collapsibleIconClassName)], [">"]),
    ]
  );
};

export const panelView = <ParentMessage>({
  open,
  children,
  id,
  keepMounted = false,
  hiddenUntilFound = false,
  className,
  style,
}: PanelViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...(id === undefined ? [] : [h.Id(id)]),
      ...openAttributes(h, open),
      ...(!open && hiddenUntilFound
        ? [h.Attribute("hidden", "until-found")]
        : []),
      ...(!open && keepMounted && !hiddenUntilFound
        ? [h.Attribute("hidden", "")]
        : []),
      h.Style({
        "--collapsible-panel-height": "auto",
        "--collapsible-panel-width": "auto",
        ...style,
      }),
      h.Class(classNames(collapsiblePanelClassName, className)),
    ],
    open || keepMounted || hiddenUntilFound ? children : []
  );
};

export const contentView = <ParentMessage>(
  children: readonly Html[],
  className?: string
): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [h.Class(classNames(collapsibleContentClassName, className))],
    [...children]
  );
};

export const collapsibleRootClassName =
  "w-full max-w-sm rounded-lg border border-gray-200 bg-white p-3 shadow-sm";

export const collapsibleTriggerClassName =
  "group flex w-full items-center justify-between gap-3 rounded-md px-2 py-2 text-left text-sm font-medium text-gray-950 transition-colors hover:bg-gray-50 data-[panel-open]:bg-gray-50 focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent-600 disabled:cursor-not-allowed disabled:opacity-50";

export const collapsibleIconClassName =
  "text-gray-500 transition-transform group-data-[panel-open]:rotate-90";

export const collapsiblePanelClassName =
  "mt-2 overflow-hidden rounded-md border border-gray-100 bg-gray-50 text-sm text-gray-700 data-[closed]:hidden";

export const collapsibleContentClassName = "space-y-1 p-3";

import { Scene } from "foldkit";
import { html } from "foldkit/html";
import { describe, expect, test } from "vitest";

import * as Collapsible from ".";

const view = (open: boolean, disabled = false) =>
  Collapsible.rootView<string>({
    open,
    disabled,
    children: [
      Collapsible.triggerView({
        open,
        disabled,
        onOpenChange: "ClickedTrigger",
        ariaLabel: "Recovery keys",
        panelId: "recovery-keys-panel",
        children: [html<string>().span([], ["Recovery keys"])],
      }),
      Collapsible.panelView({
        open,
        id: "recovery-keys-panel",
        children: [
          Collapsible.contentView([
            html<string>().div([], ["alien-bean-pasta"]),
            html<string>().div([], ["wild-irish-burrito"]),
            html<string>().div([], ["horse-battery-staple"]),
          ]),
        ],
      }),
    ],
  });

describe("Collapsible registry component", () => {
  test("renders closed trigger and omits panel content by default", () => {
    Scene.scene(
      {
        update: (model: boolean) => [model, []] as const,
        view,
      },
      Scene.with(false),
      Scene.expect(Scene.role("button", { name: "Recovery keys" })).toHaveAttr(
        "aria-expanded",
        "false"
      ),
      Scene.expect(Scene.text("alien-bean-pasta")).not.toExist()
    );
  });

  test("renders open panel state and content", () => {
    Scene.scene(
      {
        update: (model: boolean) => [model, []] as const,
        view,
      },
      Scene.with(true),
      Scene.expect(Scene.role("button", { name: "Recovery keys" })).toHaveAttr(
        "aria-expanded",
        "true"
      ),
      Scene.expect(Scene.text("alien-bean-pasta")).toExist()
    );
  });

  test("does not emit click messages when disabled", () => {
    Scene.scene(
      {
        update: (model: boolean) => [model, []] as const,
        view: (open) => view(open, true),
      },
      Scene.with(false),
      Scene.expect(Scene.role("button", { name: "Recovery keys" })).toHaveAttr(
        "disabled",
        "true"
      )
    );
  });

  test("exports Base UI state class hooks", () => {
    expect(Collapsible.collapsibleRootClassName).toContain("rounded-lg");
    expect(Collapsible.collapsibleTriggerClassName).toContain(
      "data-[panel-open]"
    );
    expect(Collapsible.collapsiblePanelClassName).toContain("data-[closed]");
  });
});
